import {Atlas} from './graph.js';
export function initKnowledge({connection,currentDocument,openDocument,askAI}){
 const entry=document.createElement('button');entry.textContent='◇ Knowledge';document.querySelector('.workspace-switcher').append(entry);
 const dialog=document.createElement('dialog');dialog.className='workspace-dialog knowledge-dialog';
 dialog.innerHTML=`<div class="spot-head"><span>KNOWLEDGE · ENTITIES & EVIDENCE</span><button data-close aria-label="Close knowledge graph">×</button></div><div class="workspace-content">
 <p>Explore typed relationships independently of Graphify. Keep imported evidence, or extract new relationships using your own connected AI. Your source files stay untouched.</p>
 <div class="knowledge-controls"><label>Saved knowledge graphs<select data-library aria-label="Saved knowledge graphs"></select></label><label>Import Graphify or Adamantium JSON<input data-import type="file" accept=".json,application/json"></label></div>
 <details><summary>Extract a new knowledge graph</summary><p>One explicit request to your connected provider. Up to 10,000 characters per selected document will leave this computer (Assistant: one document, 2,400 characters). Provider charges may apply. Quotes are checked locally; model interpretations remain unverified.</p><div class="workspace-row"><button data-add>Add open document</button><button data-clear>Clear selection</button><button data-extract>Extract selected documents</button></div><div data-documents></div><label><input data-consent type="checkbox">I approve sharing these documents with my connected provider and its usage cost for this extraction.</label></details>
 <p data-status role="status">No source information has been sent.</p><div class="knowledge-controls"><label>Find entities<input data-search placeholder="Search names, source files, and concepts"></label><label>Relationship groups<select data-groups aria-label="Relationship groups"><option value="">All entities</option></select></label></div>
 <div class="project-map"><canvas data-canvas aria-label="Evidence-linked knowledge graph"></canvas></div><div class="workspace-row"><button data-fit>Fit</button><button data-overview>Overview</button><button data-start disabled>Route from selected</button><button data-end disabled>Trace to selected</button><a data-export download>Export with provenance</a></div><p data-count></p><div data-results class="knowledge-results"></div><div data-relations class="knowledge-relations"></div></div>`;
 document.body.append(dialog);const $=s=>dialog.querySelector(s);let graph,graphId='',focus='',selected='',routeStart='',sequence=0,librarySequence=0,groupSequence=0,timer,busy=false,documents=new Map();
 const ask=document.createElement('button');ask.textContent='Ask my AI about selected entity';ask.disabled=true;$('[data-start]').before(ask);
 const context=document.createElement('a');context.textContent='Download bounded AI context';context.hidden=true;context.download='adamantium-context.json';ask.after(context);
 const exports=document.createElement('div');exports.className='workspace-row';$('[data-count]').before(exports);
 for(const [format,title] of [['canvas','Canvas'],['mermaid','Mermaid'],['md','Markdown'],['graphml','GraphML'],['svg','SVG'],['html','Offline HTML']]){
  const link=document.createElement('a');link.textContent=`Export focused view · ${title}`;link.download=`adamantium-knowledge.${format}`;link.href='#';
  link.onclick=event=>{if(!graphId){event.preventDefault();return;}link.href='/api/knowledge/export?'+new URLSearchParams({graph:graphId,format,scope:'view',q:$('[data-search]').value,focus,group:$('[data-groups]').value});};exports.append(link);
 }
 ask.onclick=()=>{if(!selected)return;dialog.close();askAI({graphId,nodeId:selected,title:graph.nodes.find(n=>n.id===selected)?.title||'Selected entity'});};
 const get=async(action,params={})=>{const r=await fetch('/api/knowledge'+(action?'/'+action+'?'+new URLSearchParams({graph:graphId,...params}):''));const data=await r.json();if(!r.ok)throw Error(data.error);return data;};
 const post=async(action,input)=>{const r=await fetch('/api/knowledge/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const data=await r.json();if(!r.ok)throw Error(data.error);return data;};
 const fail=e=>$('[data-status]').textContent=e.message;
 const operations=document.createElement('div');operations.className='workspace-row';const cluster=document.createElement('button');cluster.textContent='Discover structural communities';const merge=document.createElement('button');merge.textContent='Combine with another graph';operations.append(cluster,merge);$('[data-status]').before(operations);
 const combinePanel=document.createElement('div');combinePanel.hidden=true;const choice=document.createElement('select');choice.setAttribute('aria-label','Second graph to combine');const combine=document.createElement('button');combine.textContent='Save combined graph';combinePanel.append(choice,combine);operations.after(combinePanel);
 cluster.onclick=async()=>{if(!graphId||busy)return;busy=true;cluster.disabled=true;merge.disabled=true;try{$('[data-status]').textContent='Discovering connectivity groups in a background worker. Original graph stays unchanged…';const saved=await post('operate',{action:'cluster',ids:[graphId],title:'Communities · '+$('[data-library]').selectedOptions[0].textContent.split(' · ').slice(0,-1).join(' · ')});reset();await library(saved.id);$('[data-status]').textContent=`${saved.analysis.communities.toLocaleString()} structural communities · ${saved.analysis.isolated.toLocaleString()} isolated entities. These are connectivity groups, not model-written conclusions.`;}catch(e){fail(e);}finally{busy=false;cluster.disabled=false;merge.disabled=false;}};
 merge.onclick=async()=>{try{const rows=await get('');choice.replaceChildren();for(const row of rows.filter(r=>r.id!==graphId)){const option=document.createElement('option');option.value=row.id;option.textContent=row.title;choice.append(option);}combinePanel.hidden=false;combine.disabled=!choice.options.length;$('[data-status]').textContent='Combining preserves separate source identities and evidence. It does not invent cross-project links or overwrite either original.';}catch(e){fail(e);}};
 combine.onclick=async()=>{if(busy||!graphId||!choice.value)return;busy=true;combine.disabled=true;try{$('[data-status]').textContent='Combining graph snapshots locally…';const saved=await post('operate',{action:'combine',ids:[graphId,choice.value],title:'Combined · '+choice.selectedOptions[0].textContent});combinePanel.hidden=true;reset();await library(saved.id);}catch(e){fail(e);}finally{busy=false;combine.disabled=false;}};
 async function library(preferred){const ticket=++librarySequence,entries=await get('');if(ticket!==librarySequence)return;$('[data-library]').replaceChildren();for(const item of entries){const option=document.createElement('option');option.value=item.id;option.textContent=`${item.title} · ${item.nodes.toLocaleString()} entities`; $('[data-library]').append(option);}graphId=preferred||entries[0]?.id||'';if(graphId){$('[data-library]').value=graphId;await groups();if(ticket===librarySequence)await show();}}
 async function groups(){const ticket=++groupSequence,selectedGraph=graphId,entries=await get('groups');if(ticket!==groupSequence||selectedGraph!==graphId)return;$('[data-groups]').replaceChildren();const all=document.createElement('option');all.value='';all.textContent='All entities';$('[data-groups]').append(all);for(const group of entries){const option=document.createElement('option');option.value=group.id;option.textContent=`${group.title} · ${group.count} members${group.missing?' · '+group.missing+' missing':''}`;$('[data-groups]').append(option);}}
 function draw(data){
  graph||=new Atlas($('[data-canvas]'),{select:id=>select(id).catch(fail),expand:id=>{focus=id;show().then(()=>select(id)).catch(fail);}});graph.undirected=data.directed===false;graph.setData({...data,nodes:data.nodes.map(n=>({...n,folder:n.community||n.kind}))});graph.refresh();
  $('[data-count]').textContent=`${data.nodes.length.toLocaleString()} of ${data.totalNodes.toLocaleString()} entities · ${data.edges.length.toLocaleString()} visible relationships`;
  $('[data-results]').replaceChildren();for(const node of data.nodes.slice(0,60)){const b=document.createElement('button');b.textContent=node.title+' · '+node.kind;b.onclick=()=>select(node.id).catch(fail);$('[data-results]').append(b);}
 }
 async function show(){if(!graphId)return;const ticket=++sequence,data=await get('view',{q:$('[data-search]').value,focus});if(ticket!==sequence)return;draw(data);$('[data-status]').textContent=(data.warnings||[]).join(' ')||'Imported relationships retain their original source labels; independent verification is still required.';$('[data-export]').href='/api/knowledge/export?'+new URLSearchParams({graph:graphId});}
 async function select(id){
  selected=id;graph?.select(id);ask.disabled=false;context.hidden=false;context.href='/api/knowledge/context?'+new URLSearchParams({graph:graphId,id});$('[data-start]').disabled=false;$('[data-end]').disabled=!routeStart;const selectedGraph=graphId;
  const data=await get('relations',{id});if(selected!==id||graphId!==selectedGraph)return;
  $('[data-relations]').replaceChildren();
  for(const direction of ['incoming','outgoing']){const section=document.createElement('section'),h=document.createElement('h3');h.textContent=`${graph.undirected?(direction==='incoming'?'Related · stored as target':'Related · stored as source'):(direction==='incoming'?'Incoming':'Outgoing')} · ${data[direction+'Total']}`;section.append(h);
   for(const edge of data[direction]){const card=document.createElement('article'),b=document.createElement('button'),quote=document.createElement('blockquote'),source=document.createElement('small');b.textContent=`${graph.undirected?'—':direction==='incoming'?'←':'→'} ${edge.type} · ${edge.node.title}`;b.onclick=()=>{focus=edge.node.id;show().then(()=>select(edge.node.id)).catch(fail);};quote.textContent=edge.quote||'No supporting quotation supplied.';source.textContent=[edge.origin,edge.path,edge.location,edge.confidence!==null&&edge.confidence!==undefined?'Provider confidence: '+edge.confidence:''].filter(Boolean).join(' · ');card.append(b,quote,source);section.append(card);}
   for(const [index,card] of [...section.querySelectorAll('article')].entries()){
    const edge=data[direction][index],verify=document.createElement('button');verify.textContent='Check source evidence';
    verify.onclick=async()=>{try{const result=await get('evidence',{edge:edge.edgeIndex});const status=document.createElement('p');status.textContent=result.status;verify.replaceWith(status);if(result.documentId){const open=document.createElement('button');open.textContent=result.sourceVerified?'Open verified source':'Open current source (not verified)';open.onclick=()=>{dialog.close();openDocument(result.documentId);};status.after(open);}}catch(e){fail(e);}};card.append(verify);
   }
   $('[data-relations]').append(section);
  }
 }
 function reset(){focus='';selected='';routeStart='';sequence++;ask.disabled=true;context.hidden=true;$('[data-start]').disabled=true;$('[data-end]').disabled=true;$('[data-search]').value='';$('[data-relations]').replaceChildren();}
 entry.onclick=()=>{dialog.showModal();library(graphId).catch(fail);};$('[data-close]').onclick=()=>dialog.close();dialog.onclose=()=>{sequence++;clearTimeout(timer);};
 $('[data-library]').onchange=()=>{const ticket=++librarySequence;graphId=$('[data-library]').value;reset();groups().then(()=>{if(ticket===librarySequence)return show();}).catch(fail);};
 $('[data-groups]').onchange=async()=>{try{const id=$('[data-groups]').value;reset();if(!id)return await show();const ticket=++sequence,data=await get('group',{id});if(ticket!==sequence)return;draw(data);$('[data-status]').textContent=`${data.title}: ${data.relation} · ${data.path||'no source path'} · ${data.missing} unresolved members${data.limited?' · 900-member display limit':''}. Group membership is not a causal connection; only existing pairwise edges are drawn.`;}catch(e){fail(e);}};
 $('[data-search]').oninput=()=>{focus='';clearTimeout(timer);timer=setTimeout(()=>show().catch(fail),200);};
 $('[data-fit]').onclick=()=>graph?.fit();$('[data-overview]').onclick=()=>{reset();show().catch(fail);};
 $('[data-start]').onclick=()=>{routeStart=selected;$('[data-end]').disabled=false;$('[data-status]').textContent='Select a destination entity, then Trace to selected.';};
 $('[data-end]').onclick=async()=>{try{const data=await get('path',{from:routeStart,to:selected});if(data.path.length)draw(data);$('[data-status]').textContent=data.path.length?`${data.path.length-1} ${data.directed?'directed':'undirected'} relationship steps. Relationships may be inferred; inspect their evidence.`:data.limited?'Search reached its limit. Narrow the graph.':'No relationship path found.';}catch(e){fail(e);}};
 $('[data-import]').onchange=async e=>{
  const file=e.target.files[0];if(!file||busy)return;busy=true;
  try{if(file.size>256*1024*1024)throw Error('Import a graph JSON under 256 MiB.');$('[data-status]').textContent='Uploading locally; graph validation runs in a background worker…';const response=await fetch('/api/knowledge/import?raw=1&'+new URLSearchParams({title:file.name}),{method:'POST',headers:{'Content-Type':'application/json'},body:file});const result=await response.json();if(!response.ok)throw Error(result.error);reset();await library(result.id);}catch(error){fail(error);}finally{busy=false;e.target.value='';}
 };
 function choices(){const container=$('[data-documents]');container.replaceChildren();for(const doc of documents.values()){const b=document.createElement('button');b.textContent='Remove: '+doc.title;b.onclick=()=>{documents.delete(doc.id);choices();};container.append(b);}$('[data-consent]').checked=false;}
 $('[data-add]').onclick=()=>{const doc=currentDocument();if(!doc)return fail(Error('Open a vault document first.'));if(documents.size>=8&&!documents.has(doc.id))return fail(Error('Select up to eight documents per request.'));documents.set(doc.id,{id:doc.id,title:doc.title});choices();};
 $('[data-clear]').onclick=()=>{documents.clear();choices();};
 $('[data-extract]').onclick=async()=>{
  if(busy)return;const ai=connection();if(!ai)return fail(Error('Connect your AI in the AI workspace first.'));
  if(ai.kind==='assistant'&&documents.size!==1)return fail(Error('Select one document for Assistant’s bounded extraction request.'));
  if(!$('[data-consent]').checked)return fail(Error('Approve document sharing and provider cost before extracting.'));
  if(!documents.size)return fail(Error('Add one or more open documents first.'));busy=true;$('[data-extract]').disabled=true;
  try{$('[data-status]').textContent='Extracting with your provider; validating every evidence quote…';const saved=await post(ai.kind==='assistant'?'assistant-extract':'extract',{connectionId:ai.id,documentIds:[...documents.keys()],allowContext:true,title:'Entities · '+[...documents.values()].map(d=>d.title).join(', ')});reset();await library(saved.id);$('[data-status]').textContent+=` ${saved.rejected} unsupported claims rejected.`;}catch(e){fail(e);}finally{busy=false;$('[data-extract]').disabled=false;$('[data-consent]').checked=false;}
 };
 return {open:async selection=>{if(!dialog.open)dialog.showModal();reset();try{await library(selection.graphId);focus=selection.nodeId;await show();await select(selection.nodeId);}catch(e){fail(e);}}};
}
